css:
.transportador {
  width: 100%;
  height: 100%;
  overflow: hidden;
  opacity: var(--w-opacity);
}

.esquema {
  display: block;
  width: 100%;
  height: 100%;
}

/* Fondo gris semejante al SCADA antiguo */
.fondo {
  fill: #d5d5dd;
  stroke: var(--w-border-color);
  stroke-width: 2;
}

/* Guías laterales */
.guias path {
  fill: none;
  stroke: #4b5563;
  stroke-width: 5;
  stroke-linecap: round;
}

/* Estructura portante */
.estructura rect {
  fill: #f8fafc;
  stroke: #4b5563;
  stroke-width: 5;
}

.estructura line {
  stroke: #596275;
  stroke-width: 4;
}

/* Tejido o material transportado */
.tejido-fondo {
  fill: #f8fafc;
}

.onda {
  fill: none;
  stroke: #556070;
  stroke-width: 3;
}

.material {
  stroke: #505968;
  stroke-width: 2;
}

/* Línea central que indica movimiento */
.flujo {
  fill: none;
  stroke: var(--w-color);
  stroke-width: 3;
  stroke-dasharray: 14 10;
  opacity: 0.18;

  animation: avanzar 0.75s linear infinite;
  animation-play-state: paused;
}

/* Rodillos */
.rodillo-cuerpo {
  fill: #c5c7cd;
  stroke: #4b5563;
  stroke-width: 5;
}

.rodillo-movimiento {
  fill: none;
  stroke: var(--w-color);
  stroke-width: 3;
  stroke-dasharray: 9 8;
  opacity: 0.2;

  animation: girar-borde 0.7s linear infinite;
  animation-play-state: paused;
}

.eje {
  fill: #697386;
  stroke: #4b5563;
  stroke-width: 2;
}

/* Arcos coloreados de contacto */
.contactos path {
  fill: none;
  stroke: var(--w-color);
  stroke-width: 6;
  stroke-linecap: round;
  opacity: 0.35;
}

/* Mecanismo inferior central */
.mecanismo {
  fill: none;
  stroke: var(--w-color);
  stroke-width: 5;
  stroke-linecap: square;
  stroke-linejoin: round;
}

.mecanismo rect {
  fill: color-mix(in srgb, var(--w-color) 20%, transparent);
}

.mecanismo circle {
  fill: var(--w-color);
}

/* Línea inferior de referencia */
.linea-inferior {
  stroke: var(--w-color);
  stroke-width: 3;
  opacity: 0.35;
}

/* Nombre y estado */
.nombre {
  fill: #374151;
  font-size: calc(var(--w-font-size) * 1.25);
  font-weight: var(--w-bold);
  font-family: Arial, sans-serif;
}

.estado-texto {
  fill: #596275;
  font-size: var(--w-font-size);
  font-weight: var(--w-bold);
  font-family: Arial, sans-serif;
}

.estado-punto {
  fill: #64748b;
  stroke: #475569;
  stroke-width: 2;
}

/* Estado en funcionamiento */
.transportador.running .flujo,
.transportador.running .rodillo-movimiento {
  animation-play-state: running;
  opacity: 1;
}

.transportador.running .contactos path {
  opacity: 1;
  filter: drop-shadow(0 0 5px var(--w-color));
}

.transportador.running .mecanismo {
  filter: drop-shadow(0 0 3px var(--w-color));
}

.transportador.running .estado-punto {
  fill: var(--w-color);
  stroke: var(--w-color);
  filter: drop-shadow(0 0 5px var(--w-color));
}

/* Desplazamiento aparente de la banda */
@keyframes avanzar {
  from {
    stroke-dashoffset: 0;
  }

  to {
    stroke-dashoffset: -48;
  }
}

/* Rotación aparente de los rodillos */
@keyframes girar-borde {
  from {
    stroke-dashoffset: 0;
  }

  to {
    stroke-dashoffset: -34;
  }
}

/* Evita movimiento si Windows tiene activada esta preferencia */
@media (prefers-reduced-motion: reduce) {
  .flujo,
  .rodillo-movimiento {
    animation: none;
  }
}

js:
window.onWidgetUpdate = function (w) {
  var transportador = document.querySelector('.transportador');

  if (!transportador) return;

  /*
   * w.on será:
   *   true  cuando el BOOL del PLC esté activo
   *   false cuando esté inactivo
   */
  transportador.classList.toggle('running', w.on);
};
